parameters.jsCode:
// Accept any shape n8n LLM nodes produce (raw HTTP Request to Chat
// Completions, or the native 'Message a model' node), parse the
// model's JSON, hand it back verbatim. On junk, answer with the
// {error} shape the app treats as a provider failure.
const j = $json;
const fromResponses = Array.isArray(j.output)
  ? j.output.flatMap(o => o.content ?? []).find(c => c.text)?.text
  : undefined;
let content =
  j.choices?.[0]?.message?.content
  ?? fromResponses
  ?? j.message?.content
  ?? j.output_text
  ?? j.text;
try {
  if (content && typeof content === 'object') return [{ json: content }];
  return [{ json: JSON.parse(content) }];
} catch (e) {
  return [{ json: { error: `unparseable model output: ${String(content).slice(0, 200)}` } }];
}
